pred_sql:
SELECT s.School, s.MailZip
FROM schools s
WHERE s.AdmFName1 = 'Avetik' AND s.AdmLName1 = 'Atoian';

SELECT promoTypes 
FROM cards 
WHERE name = 'Duress';

SELECT DISTINCT layout
FROM cards
WHERE keywords LIKE '%Flying%';

SELECT name 
FROM sets 
WHERE type = 'expansion';

SELECT artist
FROM cards
WHERE name = 'Battra, Dark Destroyer';

SELECT mcmName 
FROM sets 
WHERE releaseDate = '2017-06-09';

SELECT COUNT(*) 
FROM Player 
WHERE player_name LIKE 'Aaron%' AND birthday > '1990-01-01';

SELECT COUNT(*) 
FROM card 
WHERE type = 'classic' AND issued = 'yes';

SELECT COUNT(wins) 
FROM driverStandings 
WHERE position = 91;

SELECT 
    (SELECT COUNT(*) FROM superhero AS s JOIN publisher AS p ON s.publisher_id = p.id WHERE p.publisher_name = 'DC Comics') -
    (SELECT COUNT(*) FROM superhero AS s JOIN publisher AS p ON s.publisher_id = p.id WHERE p.publisher_name = 'Marvel Comics') AS difference;

SELECT label FROM molecule WHERE molecule_id NOT IN (
    SELECT molecule_id FROM atom WHERE element = 'tin'
);

SELECT SUM(CASE WHEN molecule.label LIKE '%carcinogenic%' THEN 1 ELSE 0 END) - 
       SUM(CASE WHEN molecule.label NOT LIKE '%carcinogenic%' THEN 1 ELSE 0 END) AS difference
FROM molecule;
